package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"zoxide/internal/commands"
)

const Version = "zoxide 0.9.9"

const envVarsHelp = `Environment variables:
  _ZO_DATA_DIR          Path for zoxide data files
  _ZO_ECHO              Print the matched directory before navigating to it when set to 1
  _ZO_EXCLUDE_DIRS      List of directory globs to be excluded
  _ZO_FZF_OPTS          Custom flags to pass to fzf
  _ZO_MAXAGE            Maximum total age after which entries start getting deleted
  _ZO_RESOLVE_SYMLINKS  Resolve symlinks when storing paths`

var progName string

func ProgName() string {
	if progName != "" {
		return progName
	}
	name := os.Args[0]
	name = filepath.Base(name)
	if name == "" || name == "." || name == "/" {
		name = "zoxide"
	}
	return name
}

func Run(args []string) int {
	// Main command parsing
	// Handle --help/-h and --version/-V as global options before subcommand
	i := 0
	for i < len(args) {
		a := args[i]
		switch a {
		case "-h", "--help":
			fmt.Println(mainHelp())
			return 0
		case "-V", "--version":
			fmt.Println(Version)
			return 0
		case "--":
			// treat as no subcommand
			i = len(args)
		default:
			if strings.HasPrefix(a, "-") {
				errUnknownArg(a, "<COMMAND>")
				return 2
			}
			return dispatch(a, args[i+1:])
		}
		break
	}
	// No subcommand
	fmt.Fprintln(os.Stderr, mainHelp())
	return 2
}

func dispatch(sub string, args []string) int {
	switch sub {
	case "add":
		return commands.RunAdd(args, cmdCtx("add"))
	case "edit":
		return commands.RunEdit(args, cmdCtx("edit"))
	case "import":
		return commands.RunImport(args, cmdCtx("import"))
	case "init":
		return commands.RunInit(args, cmdCtx("init"))
	case "query":
		return commands.RunQuery(args, cmdCtx("query"))
	case "remove":
		return commands.RunRemove(args, cmdCtx("remove"))
	default:
		fmt.Fprintf(os.Stderr, "error: unrecognized subcommand '%s'\n\nUsage: %s <COMMAND>\n\nFor more information, try '--help'.\n", sub, ProgName())
		return 2
	}
}

func cmdCtx(name string) commands.Ctx {
	return commands.Ctx{
		ProgName: ProgName(),
		SubName:  name,
	}
}

func mainHelp() string {
	prog := ProgName()
	return strings.Join([]string{
		"zoxide 0.9.9",
		"Ajeet D'Souza <98ajeet@gmail.com>",
		"https://github.com/ajeetdsouza/zoxide",
		"",
		"A smarter cd command for your terminal",
		"",
		"Usage:",
		"  " + prog + " <COMMAND>",
		"",
		"Commands:",
		"  add     Add a new directory or increment its rank",
		"  edit    Edit the database",
		"  import  Import entries from another application",
		"  init    Generate shell configuration",
		"  query   Search for a directory in the database",
		"  remove  Remove a directory from the database",
		"",
		"Options:",
		"  -h, --help     Print help",
		"  -V, --version  Print version",
		"",
		envVarsHelp,
	}, "\n")
}

func errUnknownArg(arg, usageTail string) {
	fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n", arg)
	if strings.HasPrefix(arg, "-") {
		fmt.Fprintf(os.Stderr, "  tip: to pass '%s' as a value, use '-- %s'\n\n", arg, arg)
	}
	fmt.Fprintf(os.Stderr, "Usage: %s %s\n\nFor more information, try '--help'.\n", ProgName(), usageTail)
}

