package util

// JaroWinkler returns Jaro-Winkler similarity between s1 and s2.
func JaroWinkler(s1, s2 string) float64 {
	j := jaro(s1, s2)
	if j < 0.7 {
		return j
	}
	// Prefix bonus
	prefix := 0
	maxPrefix := 4
	if len(s1) < maxPrefix {
		maxPrefix = len(s1)
	}
	if len(s2) < maxPrefix {
		maxPrefix = len(s2)
	}
	for i := 0; i < maxPrefix; i++ {
		if s1[i] != s2[i] {
			break
		}
		prefix++
	}
	return j + float64(prefix)*0.1*(1-j)
}

func jaro(s1, s2 string) float64 {
	if len(s1) == 0 && len(s2) == 0 {
		return 1
	}
	if len(s1) == 0 || len(s2) == 0 {
		return 0
	}
	if s1 == s2 {
		return 1
	}
	maxDist := len(s1)
	if len(s2) > maxDist {
		maxDist = len(s2)
	}
	maxDist = maxDist/2 - 1
	if maxDist < 0 {
		maxDist = 0
	}
	m1 := make([]bool, len(s1))
	m2 := make([]bool, len(s2))
	m := 0
	for i := 0; i < len(s1); i++ {
		lo := i - maxDist
		if lo < 0 {
			lo = 0
		}
		hi := i + maxDist
		if hi >= len(s2) {
			hi = len(s2) - 1
		}
		for j := lo; j <= hi; j++ {
			if m2[j] {
				continue
			}
			if s1[i] != s2[j] {
				continue
			}
			m1[i] = true
			m2[j] = true
			m++
			break
		}
	}
	if m == 0 {
		return 0
	}
	// Transpositions
	t := 0
	k := 0
	for i := 0; i < len(s1); i++ {
		if !m1[i] {
			continue
		}
		for !m2[k] {
			k++
		}
		if s1[i] != s2[k] {
			t++
		}
		k++
	}
	t /= 2
	fm := float64(m)
	return (fm/float64(len(s1)) + fm/float64(len(s2)) + (fm-float64(t))/fm) / 3
}

// SuggestFor finds the closest match in candidates for the input string.
// Returns empty string if no match is above threshold.
func SuggestFor(input string, candidates []string) string {
	best := ""
	bestScore := 0.0
	threshold := 0.7
	for _, c := range candidates {
		s := JaroWinkler(lower(input), lower(c))
		if s > bestScore {
			bestScore = s
			best = c
		}
	}
	if bestScore >= threshold {
		return best
	}
	return ""
}

func lower(s string) string {
	b := make([]byte, len(s))
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= 'A' && c <= 'Z' {
			c += 32
		}
		b[i] = c
	}
	return string(b)
}
