package db

import (
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"math"
	"os"
	"path/filepath"
	"sort"
	"time"

	"zoxide/internal/util"
)

const (
	Version       uint32 = 3
	DefaultMaxAge float64 = 10000
)

type Entry struct {
	Path     string
	Rank     float64
	LastAccessed uint64
}

type DB struct {
	Dir     string
	Path    string
	Entries []Entry
	dirty   bool
}

// Open opens the database from disk (or creates empty if missing).
func Open(dir string) (*DB, error) {
	if err := os.MkdirAll(dir, 0755); err != nil {
		return nil, fmt.Errorf("unable to create data directory: %s: %w", dir, err)
	}
	dbPath := filepath.Join(dir, "db.zo")
	d := &DB{Dir: dir, Path: dbPath}
	f, err := os.Open(dbPath)
	if err != nil {
		if os.IsNotExist(err) {
			return d, nil
		}
		return nil, fmt.Errorf("could not open database: %s: %w", dbPath, err)
	}
	defer f.Close()
	buf, err := io.ReadAll(f)
	if err != nil {
		return nil, fmt.Errorf("could not read database: %s: %w", dbPath, err)
	}
	if len(buf) == 0 {
		return d, nil
	}
	if err := d.decode(buf); err != nil {
		return nil, fmt.Errorf("could not deserialize database: %s: %w", dbPath, err)
	}
	return d, nil
}

func (d *DB) decode(buf []byte) error {
	if len(buf) < 12 {
		return errors.New("database too small")
	}
	ver := binary.LittleEndian.Uint32(buf[0:4])
	if ver != Version {
		return fmt.Errorf("unsupported version: %d", ver)
	}
	n := binary.LittleEndian.Uint64(buf[4:12])
	idx := 12
	for i := uint64(0); i < n; i++ {
		if idx+8 > len(buf) {
			return errors.New("malformed entry")
		}
		plen := binary.LittleEndian.Uint64(buf[idx : idx+8])
		idx += 8
		if idx+int(plen)+16 > len(buf) {
			return errors.New("malformed entry")
		}
		path := string(buf[idx : idx+int(plen)])
		idx += int(plen)
		rank := math.Float64frombits(binary.LittleEndian.Uint64(buf[idx : idx+8]))
		idx += 8
		last := binary.LittleEndian.Uint64(buf[idx : idx+8])
		idx += 8
		d.Entries = append(d.Entries, Entry{Path: path, Rank: rank, LastAccessed: last})
	}
	return nil
}

// Save atomically writes the database to disk.
func (d *DB) Save() error {
	if !d.dirty {
		return nil
	}
	// Compute total size
	size := 12
	for _, e := range d.Entries {
		size += 8 + len(e.Path) + 8 + 8
	}
	buf := make([]byte, size)
	binary.LittleEndian.PutUint32(buf[0:4], Version)
	binary.LittleEndian.PutUint64(buf[4:12], uint64(len(d.Entries)))
	idx := 12
	for _, e := range d.Entries {
		binary.LittleEndian.PutUint64(buf[idx:idx+8], uint64(len(e.Path)))
		idx += 8
		copy(buf[idx:idx+len(e.Path)], e.Path)
		idx += len(e.Path)
		binary.LittleEndian.PutUint64(buf[idx:idx+8], math.Float64bits(e.Rank))
		idx += 8
		binary.LittleEndian.PutUint64(buf[idx:idx+8], e.LastAccessed)
		idx += 8
	}
	// Atomic write via temp file
	tmp, err := util.TempFile(d.Dir, "tmp_")
	if err != nil {
		return fmt.Errorf("could not create temporary database: %w", err)
	}
	tmpPath := tmp.Name()
	defer func() {
		if tmp != nil {
			tmp.Close()
			os.Remove(tmpPath)
		}
	}()
	if _, err := tmp.Write(buf); err != nil {
		return fmt.Errorf("could not write to temporary database: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("could not close temporary database: %w", err)
	}
	tmp = nil
	if err := os.Rename(tmpPath, d.Path); err != nil {
		return fmt.Errorf("could not rename temporary database: %w", err)
	}
	d.dirty = false
	return nil
}

// Add adds a new entry or increments an existing one.
func (d *DB) Add(path string, by float64, now uint64) {
	for i := range d.Entries {
		if d.Entries[i].Path == path {
			d.Entries[i].Rank += by
			if d.Entries[i].Rank < 0 {
				d.Entries[i].Rank = 0
			}
			d.Entries[i].LastAccessed = now
			d.dirty = true
			d.age()
			return
		}
	}
	d.Entries = append(d.Entries, Entry{Path: path, Rank: by, LastAccessed: now})
	d.dirty = true
	d.age()
}

// Remove removes an entry by path. Returns true if removed.
func (d *DB) Remove(path string) bool {
	for i, e := range d.Entries {
		if e.Path == path {
			d.Entries = append(d.Entries[:i], d.Entries[i+1:]...)
			d.dirty = true
			return true
		}
	}
	return false
}

// SetDirty marks the DB as needing a save.
func (d *DB) SetDirty() {
	d.dirty = true
}

func (d *DB) age() {
	maxAge := DefaultMaxAge
	if v := os.Getenv("_ZO_MAXAGE"); v != "" {
		if f, err := parseMaxAge(v); err == nil {
			maxAge = f
		}
	}
	sum := 0.0
	for _, e := range d.Entries {
		sum += e.Rank
	}
	if sum > maxAge {
		factor := 0.9 * maxAge / sum
		kept := d.Entries[:0]
		for _, e := range d.Entries {
			e.Rank *= factor
			if e.Rank >= 1 {
				kept = append(kept, e)
			}
		}
		d.Entries = kept
	}
}

// Now returns current unix time in seconds.
func Now() uint64 {
	return uint64(time.Now().Unix())
}

func parseMaxAge(s string) (float64, error) {
	var f float64
	_, err := fmt.Sscanf(s, "%f", &f)
	if err != nil {
		return 0, err
	}
	if f <= 0 {
		return 0, fmt.Errorf("invalid _ZO_MAXAGE: %s", s)
	}
	return f, nil
}

// SortByScore sorts entries by score descending.
func (d *DB) SortByScore(now uint64) []Entry {
	out := make([]Entry, len(d.Entries))
	copy(out, d.Entries)
	sort.SliceStable(out, func(i, j int) bool {
		si := Score(out[i], now)
		sj := Score(out[j], now)
		return si > sj
	})
	return out
}

// Score computes the display score of an entry.
func Score(e Entry, now uint64) float64 {
	var dur uint64
	if now > e.LastAccessed {
		dur = now - e.LastAccessed
	}
	var factor float64
	switch {
	case dur < 3600:
		factor = 4
	case dur < 86400:
		factor = 2
	case dur < 604800:
		factor = 0.5
	default:
		factor = 0.25
	}
	return e.Rank * factor
}

// FormatScore formats a score with 1 decimal, capped at 9999.
func FormatScore(s float64) string {
	if s > 9999 {
		s = 9999
	}
	return fmt.Sprintf("%6.1f", s)
}
