// DataDir returns the zoxide data directory based on env vars/platform.
func DataDir() (string, error) {
	if v := os.Getenv("_ZO_DATA_DIR"); v != "" {
		return v, nil
	}
	switch runtime.GOOS {
	case "darwin":
		home, err := os.UserHomeDir()
		if err != nil {
			return "", fmt.Errorf("could not determine home directory: %w", err)
		}
		return filepath.Join(home, "Library", "Application Support", "zoxide"), nil
	case "windows":
		if v := os.Getenv("LOCALAPPDATA"); v != "" {
			return filepath.Join(v, "zoxide"), nil
		}
		home, err := os.UserHomeDir()
		if err != nil {
			return "", err
		}
		return filepath.Join(home, "AppData", "Local", "zoxide"), nil
	default:
		if v := os.Getenv("XDG_DATA_HOME"); v != "" {
			return filepath.Join(v, "zoxide"), nil
		}
		home, err := os.UserHomeDir()
		if err != nil {
			return "", err
		}
		return filepath.Join(home, ".local", "share", "zoxide"), nil
	}
}

// TempFile creates a temporary file in the given directory with a random suffix.
func TempFile(dir, prefix string) (*os.File, error) {
	// zoxide uses `tmp_XXXXXXXXXXXX` where X is random alphanumeric
	for i := 0; i < 1000; i++ {
		name := prefix + randString(12)
		path := filepath.Join(dir, name)
		f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0644)
		if err == nil {
			return f, nil
		}
		if !os.IsExist(err) {
			return nil, err
		}
	}
	return nil, errors.New("could not create a unique temporary file")
}

func randString(n int) string {
	b := make([]byte, 9) // 9 bytes -> 12 base64 chars
	_, _ = rand.Read(b)
	s := base64.RawURLEncoding.EncodeToString(b)
	if len(s) >= n {
		return s[:n]
	}
	return s
}

// ResolvePath returns the absolute canonical form of a path. If _ZO_RESOLVE_SYMLINKS is set,
// also resolves symlinks.
func ResolvePath(p string) (string, error) {
	if p == "" {
		return "", errors.New("empty path")
	}
	var abs string
	var err error
	if filepath.IsAbs(p) {
		abs = filepath.Clean(p)
	} else {
		abs, err = filepath.Abs(p)
		if err != nil {
			return "", err
		}
	}
	if os.Getenv("_ZO_RESOLVE_SYMLINKS") == "1" {
		if r, err := filepath.EvalSymlinks(abs); err == nil {
			abs = r
		}
	}
	return abs, nil
}

// IsDir checks if the path is a directory.
func IsDir(p string) bool {
	st, err := os.Stat(p)
	if err != nil {
		return false
	}
	return st.IsDir()
}

// ExcludeDirs returns list of glob patterns from _ZO_EXCLUDE_DIRS.
func ExcludeDirs() []string {
	v := os.Getenv("_ZO_EXCLUDE_DIRS")
	if v == "" {
		return nil
	}
	sep := ":"
	if runtime.GOOS == "windows" {
		sep = ";"
	}
	parts := strings.Split(v, sep)
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		if p == "" {
			continue
		}
		out = append(out, p)
	}
	return out
}

// MatchesAnyGlob checks if path matches any of the patterns.
func MatchesAnyGlob(path string, patterns []string) bool {
	for _, p := range patterns {
		if Glob(p, path) {
			return true
		}
	}
	return false
}
