package util

// Glob returns true if s matches pattern.
// Pattern supports:
//   *         matches any sequence of characters (including /)
//   ?         matches any single character
//   [abc]     character class
//   [!abc]    negated character class
//   [a-z]     character range
//   \c        escaped character
// This is similar to fnmatch without FNM_PATHNAME.
func Glob(pattern, s string) bool {
	return glob(pattern, s)
}

func glob(pat, s string) bool {
	pi, si := 0, 0
	starP, starS := -1, -1
	for si < len(s) {
		if pi < len(pat) {
			c := pat[pi]
			switch c {
			case '?':
				pi++
				si++
				continue
			case '*':
				starP = pi
				starS = si
				pi++
				continue
			case '[':
				// character class
				end := findClose(pat, pi+1)
				if end > 0 {
					if matchClass(pat[pi+1:end], s[si]) {
						pi = end + 1
						si++
						continue
					}
				} else {
					// unclosed, treat literal
					if pat[pi] == s[si] {
						pi++
						si++
						continue
					}
				}
			case '\\':
				// escape next char
				if pi+1 < len(pat) {
					if pat[pi+1] == s[si] {
						pi += 2
						si++
						continue
					}
				} else {
					if '\\' == s[si] {
						pi++
						si++
						continue
					}
				}
			default:
				if c == s[si] {
					pi++
					si++
					continue
				}
			}
		}
		// Mismatch: backtrack to last '*' if any
		if starP >= 0 {
			pi = starP + 1
			starS++
			si = starS
			continue
		}
		return false
	}
	// Consumed all of s. Remaining pattern must be all '*'.
	for pi < len(pat) && pat[pi] == '*' {
		pi++
	}
	return pi == len(pat)
}

func findClose(pat string, start int) int {
	i := start
	if i < len(pat) && (pat[i] == '!' || pat[i] == '^') {
		i++
	}
	if i < len(pat) && pat[i] == ']' {
		i++
	}
	for i < len(pat) {
		if pat[i] == ']' {
			return i
		}
		i++
	}
	return -1
}

func matchClass(class string, c byte) bool {
	negated := false
	i := 0
	if i < len(class) && (class[i] == '!' || class[i] == '^') {
		negated = true
		i++
	}
	matched := false
	for i < len(class) {
		a := class[i]
		if i+2 < len(class) && class[i+1] == '-' {
			b := class[i+2]
			if c >= a && c <= b {
				matched = true
			}
			i += 3
		} else {
			if c == a {
				matched = true
			}
			i++
		}
	}
	if negated {
		return !matched
	}
	return matched
}
