			return 0
		case a == "-V" || a == "--version":
			fmt.Println("zoxide-remove 0.9.9")
			return 0
		case a == "--":
			i++
			paths = append(paths, args[i:]...)
			i = len(args)
		case strings.HasPrefix(a, "-"):
			unexpectedArg(ctx, a, usageTail)
			return 2
		default:
			paths = append(paths, a)
			i++
		}
	}
	if len(paths) == 0 {
		return 0
	}

	dir, err := util.DataDir()
	if err != nil {
		fatalErr(err)
		return 1
	}
	d, err := db.Open(dir)
	if err != nil {
		fatalErr(err)
		return 1
	}

	for _, p := range paths {
		abs := p
		if !strings.HasPrefix(p, "/") {
			if r, err := util.ResolvePath(p); err == nil {
				abs = r
			}
		} else {
			abs = resolveLogical(p)
		}
		if !d.Remove(abs) {
			// try without resolving symlinks
			if d.Remove(p) {
				continue
			}
			fmt.Fprintf(os.Stderr, "zoxide: path not found in database: %s\n", p)
			return 1
		}
	}
	if err := d.Save(); err != nil {
		fatalErr(err)
		return 1
	}
	return 0
}

// resolveLogical normalizes a path by removing `.`, `..` components without resolving symlinks.
func resolveLogical(p string) string {
	// Path already absolute
	parts := strings.Split(p, "/")
	stack := make([]string, 0, len(parts))
	for _, part := range parts {
		switch part {
		case "", ".":
			continue
		case "..":
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
		default:
			stack = append(stack, part)
		}
	}
	return "/" + strings.Join(stack, "/")
}

