package commands

import (
	"fmt"
	"os"
	"strings"

	"zoxide/internal/db"
	"zoxide/internal/fzf"
	"zoxide/internal/util"
)

func queryHelp(progName string) string {
	return helpHeaderFor("query", "Search for a directory in the database") + `

Usage:
  ` + progName + ` query [OPTIONS] [KEYWORDS]...

Arguments:
  [KEYWORDS]...  

Options:
  -a, --all              Show unavailable directories
  -i, --interactive      Use interactive selection
  -l, --list             List all matching directories
  -s, --score            Print score with results
      --exclude <path>   Exclude the current directory
      --base-dir <path>  Only search within this directory
  -h, --help             Print help
  -V, --version          Print version

` + envVarsHelp
}

func RunQuery(args []string, ctx Ctx) int {
	usageTail := "[OPTIONS] [KEYWORDS]..."
	var opts queryOpts
	i := 0
	for i < len(args) {
		a := args[i]
		switch {
		case a == "-h" || a == "--help":
			fmt.Println(queryHelp(ctx.ProgName))
			return 0
		case a == "-V" || a == "--version":
			fmt.Println("zoxide-query 0.9.9")
			return 0
		case a == "--":
			i++
			opts.keywords = append(opts.keywords, args[i:]...)
			i = len(args)
		case a == "-a" || a == "--all":
			opts.all = true
			i++
		case a == "-i" || a == "--interactive":
			opts.interactive = true
			i++
		case a == "-l" || a == "--list":
			opts.list = true
			i++
		case a == "-s" || a == "--score":
			opts.score = true
			i++
		case a == "--exclude":
			i++
			if i >= len(args) {
				fmt.Fprintln(os.Stderr, "error: a value is required for '--exclude <path>' but none was supplied\n\nFor more information, try '--help'.")
				return 2
			}
			opts.exclude = args[i]
			opts.excludeSet = true
			i++
		case strings.HasPrefix(a, "--exclude="):
			opts.exclude = a[len("--exclude="):]
			opts.excludeSet = true
			i++
		case a == "--base-dir":
			i++
			if i >= len(args) {
				fmt.Fprintln(os.Stderr, "error: a value is required for '--base-dir <path>' but none was supplied\n\nFor more information, try '--help'.")
				return 2
			}
			opts.baseDir = args[i]
			opts.baseDirSet = true
			i++
		case strings.HasPrefix(a, "--base-dir="):
			opts.baseDir = a[len("--base-dir="):]
			opts.baseDirSet = true
			i++
		case strings.HasPrefix(a, "-") && len(a) > 1 && a[1] != '-':
			// Multi-char short options
			for k := 1; k < len(a); k++ {
				switch a[k] {
				case 'a':
					opts.all = true
				case 'i':
					opts.interactive = true
				case 'l':
					opts.list = true
				case 's':
					opts.score = true
				default:
					unexpectedArg(ctx, "-"+string(a[k]), usageTail)
					return 2
				}
			}
			i++
		case strings.HasPrefix(a, "-"):
			unexpectedArg(ctx, a, usageTail)
			return 2
		default:
			opts.keywords = append(opts.keywords, a)
			i++
		}
	}

	dir, err := util.DataDir()
	if err != nil {
		fatalErr(err)
		return 1
	}
	d, err := db.Open(dir)
	if err != nil {
		fatalErr(err)
		return 1
	}
	now := db.Now()
	all := d.SortByScore(now)

	// Filter
	var filtered []db.Entry
	for _, e := range all {
		if opts.excludeSet && e.Path == opts.exclude {
			continue
		}
		if opts.baseDirSet && !isSubPath(e.Path, opts.baseDir) {
			continue
		}
		if !matchesKeywords(e.Path, opts.keywords) {
			continue
		}
		if !opts.all {
			if !util.IsDir(e.Path) {
				continue
			}
		}
		filtered = append(filtered, e)
	}

	if opts.interactive {
		if len(filtered) == 0 {
			fmt.Fprintln(os.Stderr, "zoxide: no match found")
			return 1
		}
		sel, err := fzf.Select(filtered, now)
		if err != nil {
			return fzf.ExitCode(err)
		}
		fmt.Println(sel)
		return 0
	}

	if opts.list {
		for _, e := range filtered {
			if opts.score {
				fmt.Printf("%s %s\n", db.FormatScore(db.Score(e, now)), e.Path)
			} else {
				fmt.Println(e.Path)
			}
		}
		return 0
	}

	if len(filtered) == 0 {
		fmt.Fprintln(os.Stderr, "zoxide: no match found")
		return 1
	}
	e := filtered[0]
	if opts.score {
		fmt.Printf("%s %s\n", db.FormatScore(db.Score(e, now)), e.Path)
	} else {
		fmt.Println(e.Path)
	}
	return 0
}

type queryOpts struct {
	all         bool
	interactive bool
	list        bool
	score       bool
	exclude     string
	excludeSet  bool
	baseDir     string
	baseDirSet  bool
	keywords    []string
}

func isSubPath(path, base string) bool {
	if path == base {
		return true
	}
	if !strings.HasSuffix(base, "/") {
		base += "/"
	}
	return strings.HasPrefix(path, base)
}

// matchesKeywords returns true if path matches all keywords in-order.
func matchesKeywords(path string, keywords []string) bool {
	p := strings.ToLower(path)
	// Last keyword must match the last path segment that begins matching
	// zoxide's matching algorithm requires keywords to match in order, with
	// the last keyword matching the final path segment.
	if len(keywords) == 0 {
		return true
	}
	start := 0
	for _, kw := range keywords {
		if kw == "" {
			continue
		}
		kwl := strings.ToLower(kw)
		idx := strings.Index(p[start:], kwl)
		if idx < 0 {
			return false
		}
		start += idx + len(kwl)
	}
	// Last keyword must match the last component
	last := strings.ToLower(keywords[len(keywords)-1])
	if strings.HasSuffix(last, "/") {
		// prefix match
		return true
	}
	// Find last '/' in path and ensure match includes that segment
	lastSlash := strings.LastIndex(p, "/")
	// The last keyword must have matched at or after lastSlash
	matchPos := strings.LastIndex(p, last)
	if matchPos < 0 {
		return false
	}
	if matchPos < lastSlash+1 {
		// last keyword matched before last slash; check if no later occurrence in last segment
		// Try to find match in the last segment
		lastSeg := p[lastSlash+1:]
		if !strings.Contains(lastSeg, last) {
			return false
		}
	}
	return true
}
