func (e *exitErr) Error() string { return fmt.Sprintf("fzf exited %d", e.code) }

// ExitCode returns the appropriate exit code for a returned error from Select.
// - nil: 0
// - fzf signaled: original code
// - fzf code 1: 1 with "no match found" message
// - other: 1
func ExitCode(err error) int {
	var e *exitErr
	if errors.As(err, &e) {
		return e.code
	}
	return 1
}

// Select runs fzf with the given entries and returns the selected path.
func Select(entries []db.Entry, now uint64) (string, error) {
	return SelectFormatted(formatEntries(entries, now))
}

func formatEntries(entries []db.Entry, now uint64) []byte {
	var buf bytes.Buffer
	for _, e := range entries {
		buf.WriteString(db.FormatScore(db.Score(e, now)))
		buf.WriteByte('\t')
		buf.WriteString(e.Path)
		buf.WriteByte(0)
	}
	return buf.Bytes()
}

// SelectFormatted runs fzf with pre-formatted input.
func SelectFormatted(input []byte) (string, error) {
	fzf, err := exec.LookPath("fzf")
	if err != nil {
		fmt.Fprintln(os.Stderr, "zoxide: could not find fzf, is it installed?")
		return "", &exitErr{code: 1}
	}
	args := buildArgs(false)
	cmd := exec.Command(fzf, args...)
	cmd.Stdin = bytes.NewReader(input)
	cmd.Stderr = os.Stderr
	var out bytes.Buffer
	cmd.Stdout = &out

	userOpts, userOptsSet := os.LookupEnv("_ZO_FZF_OPTS")
	if userOptsSet {
		env := removeEnv(os.Environ(), "FZF_DEFAULT_OPTS")
		env = append(env, "FZF_DEFAULT_OPTS="+userOpts)
		cmd.Env = env
	}

	if err := cmd.Run(); err != nil {
		if ee, ok := err.(*exec.ExitError); ok {
			code := ee.ExitCode()
			if code == 1 {
				fmt.Fprintln(os.Stderr, "zoxide: no match found")
				return "", &exitErr{code: 1}
			}
			return "", &exitErr{code: code}
		}
		return "", &exitErr{code: 1}
	}
	line := out.String()
	line = strings.TrimRight(line, "\n")
	if len(line) < 7 {
		return "", &exitErr{code: 1}
	}
	return line[7:], nil
}

func removeEnv(env []string, key string) []string {
	prefix := key + "="
	out := env[:0]
	for _, kv := range env {
		if strings.HasPrefix(kv, prefix) {
			continue
		}
		out = append(out, kv)
	}
	return out
}

// buildArgs constructs fzf args.
// If interactive=true, uses query-interactive args.
// If interactive=false (edit mode), uses edit args.
func buildArgs(forEdit bool) []string {
	if _, hasUserOpts := os.LookupEnv("_ZO_FZF_OPTS"); hasUserOpts {
		return []string{"--delimiter=\t", "--nth=2", "--read0"}
	}
	if forEdit {
		return editArgs()
	}
	return queryArgs()
