package commands

import (
	"bufio"
	"fmt"
	"io"
	"math"
	"os"
	"strconv"
	"strings"

	"zoxide/internal/db"
	"zoxide/internal/util"
)

func importHelp(progName string) string {
	return helpHeaderFor("import", "Import entries from another application") + `

Usage:
  ` + progName + ` import [OPTIONS] --from <FROM> <PATH>

Arguments:
  <PATH>  

Options:
      --from <FROM>  Application to import from [possible values: autojump, z]
      --merge        Merge into existing database
  -h, --help         Print help
  -V, --version      Print version

` + envVarsHelp
}

func RunImport(args []string, ctx Ctx) int {
	usageTail := "[OPTIONS] --from <FROM> <PATH>"
	var fromSet bool
	var from, path string
	var merge bool
	var havePath bool
	i := 0
	for i < len(args) {
		a := args[i]
		switch {
		case a == "-h" || a == "--help":
			fmt.Println(importHelp(ctx.ProgName))
			return 0
		case a == "-V" || a == "--version":
			fmt.Println("zoxide-import 0.9.9")
			return 0
		case a == "--":
			i++
			if i < len(args) {
				if havePath {
					unexpectedArg(ctx, args[i], usageTail)
					return 2
				}
				path = args[i]
				havePath = true
				i++
			}
		case a == "--from":
			i++
			if i >= len(args) {
				fmt.Fprintln(os.Stderr, "error: a value is required for '--from <FROM>' but none was supplied\n\nFor more information, try '--help'.")
				return 2
			}
			from = args[i]
			fromSet = true
			i++
		case strings.HasPrefix(a, "--from="):
			from = a[len("--from="):]
			fromSet = true
			i++
		case a == "--merge":
			merge = true
			i++
		case strings.HasPrefix(a, "-"):
			unexpectedArg(ctx, a, usageTail)
			return 2
		default:
			if havePath {
				unexpectedArg(ctx, a, usageTail)
				return 2
			}
			path = a
			havePath = true
			i++
		}
	}

	var missing []string
	if !fromSet {
		missing = append(missing, "--from <FROM>")
	}
	if !havePath {
		missing = append(missing, "<PATH>")
	}
	if len(missing) > 0 {
		fmt.Fprintln(os.Stderr, "error: the following required arguments were not provided:")
		for _, m := range missing {
			fmt.Fprintln(os.Stderr, "  "+m)
		}
		fmt.Fprintf(os.Stderr, "\nUsage: %s import --from <FROM> <PATH>\n\nFor more information, try '--help'.\n", ctx.ProgName)
		return 2
	}
	if from != "z" && from != "autojump" {
		fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--from <FROM>'\n  [possible values: autojump, z]\n\nFor more information, try '--help'.\n", from)
		return 2
	}

	dir, err := util.DataDir()
	if err != nil {
		fatalErr(err)
		return 1
	}
	d, err := db.Open(dir)
	if err != nil {
		fatalErr(err)
		return 1
	}
	if !merge && len(d.Entries) > 0 {
		fmt.Fprintln(os.Stderr, "zoxide: current database is not empty, specify --merge to continue anyway")
		return 1
	}

	f, err := os.Open(path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "zoxide: could not open database for importing: %s\n\nCaused by:\n    %s\n", path, errOSMessage(err))
		return 1
	}
	defer f.Close()

	if from == "z" {
		if err := importZ(d, f); err != nil {
			fmt.Fprintf(os.Stderr, "zoxide: import error\n\nCaused by:\n    0: %s\n    1: %s\n", err.msg, err.cause)
			return 1
		}
	} else {
		if err := importAutojump(d, f); err != nil {
			fmt.Fprintf(os.Stderr, "zoxide: import error\n\nCaused by:\n    0: %s\n    1: %s\n", err.msg, err.cause)
			return 1
		}
	}

	if err := d.Save(); err != nil {
		fatalErr(err)
		return 1
	}
	return 0
}

type importErr struct {
	msg   string
	cause string
}

func (e *importErr) Error() string { return e.msg }

func importZ(d *db.DB, r io.Reader) *importErr {
	sc := bufio.NewScanner(r)
	for sc.Scan() {
		line := sc.Text()
		if line == "" {
			continue
		}
		parts := strings.SplitN(line, "|", 3)
		if len(parts) != 3 {
			continue
		}
		path := parts[0]
		rank, err := strconv.ParseFloat(parts[1], 64)
		if err != nil {
			return &importErr{msg: "invalid rank: " + path, cause: "invalid float literal"}
		}
		last, err := strconv.ParseUint(parts[2], 10, 64)
		if err != nil {
			return &importErr{msg: "invalid last accessed: " + path, cause: "invalid integer"}
		}
		mergeEntry(d, path, rank, last)
	}
	if err := sc.Err(); err != nil {
		return &importErr{msg: "read error", cause: err.Error()}
	}
	return nil
}

func importAutojump(d *db.DB, r io.Reader) *importErr {
	sc := bufio.NewScanner(r)
	for sc.Scan() {
		line := sc.Text()
		if line == "" {
			continue
		}
		parts := strings.SplitN(line, "\t", 2)
		if len(parts) != 2 {
			continue
		}
		origRank, err := strconv.ParseFloat(parts[0], 64)
		if err != nil {
			return &importErr{msg: "invalid rank: " + parts[1], cause: "invalid float literal"}
		}
		path := parts[1]
		// zoxide autojump import applies sigmoid to rank
		rank := 1 / (1 + math.Exp(-origRank))
		mergeEntry(d, path, rank, 0)
	}
	if err := sc.Err(); err != nil {
		return &importErr{msg: "read error", cause: err.Error()}
	}
	return nil
}

func mergeEntry(d *db.DB, path string, rank float64, last uint64) {
	for i := range d.Entries {
		if d.Entries[i].Path == path {
			d.Entries[i].Rank += rank
			if last > d.Entries[i].LastAccessed {
				d.Entries[i].LastAccessed = last
			}
			d.SetDirty()
			return
		}
	}
	d.Entries = append(d.Entries, db.Entry{Path: path, Rank: rank, LastAccessed: last})
	d.SetDirty()
}

func errOSMessage(err error) string {
	// Try to match Rust-like OS error message
	s := err.Error()
	// Strip Go-specific path prefix like "open FILE: no such file or directory"
	if i := strings.LastIndex(s, ": "); i >= 0 {
		s = s[i+2:]
	}
	if strings.Contains(s, "no such file or directory") {
		return "No such file or directory (os error 2)"
	}
	if strings.Contains(s, "permission denied") {
		return "Permission denied (os error 13)"
	}
	if strings.Contains(s, "is a directory") {
		return "Is a directory (os error 21)"
	}
	return s
}
