package commands

import (
	"bytes"
	"fmt"
	"os"
	"strings"

	"zoxide/internal/db"
	"zoxide/internal/fzf"
	"zoxide/internal/util"
)

func editHelp(progName string) string {
	return helpHeaderFor("edit", "Edit the database") + `

Usage:
  ` + progName + ` edit

Options:
  -h, --help     Print help
  -V, --version  Print version

` + envVarsHelp
}

func RunEdit(args []string, ctx Ctx) int {
	usageTail := ""
	// Subcommands (hidden): reload, delete, increment, decrement
	var rest []string
	for _, a := range args {
		rest = append(rest, a)
	}
	i := 0
	for i < len(rest) {
		a := rest[i]
		switch {
		case a == "-h" || a == "--help":
			fmt.Println(editHelp(ctx.ProgName))
			return 0
		case a == "-V" || a == "--version":
			fmt.Println("zoxide-edit 0.9.9")
			return 0
		case a == "--":
			i++
			continue
		case a == "reload":
			return editReload()
		case a == "delete":
			return editDelete(rest[i+1:])
		case a == "increment":
			return editIncrement(rest[i+1:])
		case a == "decrement":
			return editDecrement(rest[i+1:])
		case strings.HasPrefix(a, "-"):
			unexpectedArg(ctx, a, usageTail)
			return 2
		default:
			// unknown non-flag arg: treat as error
			unexpectedArg(ctx, a, usageTail)
			return 2
		}
	}
	return editInteractive()
}

func openDB() (*db.DB, int) {
	dir, err := util.DataDir()
	if err != nil {
		fatalErr(err)
		return nil, 1
	}
	d, err := db.Open(dir)
	if err != nil {
		fatalErr(err)
		return nil, 1
	}
	return d, 0
}

func editReload() int {
	d, code := openDB()
	if d == nil {
		return code
	}
	return emitReload(d)
}

func emitReload(d *db.DB) int {
	now := db.Now()
	entries := d.SortByScore(now)
	// Print entries in reverse order (ascending score) for fzf
	var buf bytes.Buffer
	for i := len(entries) - 1; i >= 0; i-- {
		e := entries[i]
		buf.WriteString(db.FormatScore(db.Score(e, now)))
		buf.WriteByte('\t')
		buf.WriteString(e.Path)
		buf.WriteByte(0)
	}
	os.Stdout.Write(buf.Bytes())
	return 0
}

func editDelete(paths []string) int {
	d, code := openDB()
	if d == nil {
		return code
	}
	for _, p := range paths {
		d.Remove(p)
	}
	if err := d.Save(); err != nil {
		fatalErr(err)
		return 1
	}
	return emitReload(d)
}

func editIncrement(paths []string) int {
	d, code := openDB()
	if d == nil {
		return code
	}
	now := db.Now()
	for _, p := range paths {
		d.Add(p, 1.0, now)
	}
	if err := d.Save(); err != nil {
		fatalErr(err)
		return 1
	}
	return emitReload(d)
}

func editDecrement(paths []string) int {
