// LookPath returns the path to fzf or error.
func LookPath() (string, error) {
	return exec.LookPath("fzf")
}

// RunEdit runs fzf in edit mode. It ignores any enter selection since bindings trigger reloads.
// Returns exit code.
func RunEdit() int {
	fzfPath, err := exec.LookPath("fzf")
	if err != nil {
		fmt.Fprintln(os.Stderr, "zoxide: could not find fzf, is it installed?")
		return 1
	}
	args := buildArgs(true)
	cmd := exec.Command(fzfPath, args...)
	// No stdin needed; fzf uses start:reload binding
	cmd.Stdin = bytes.NewReader(nil)
	cmd.Stderr = os.Stderr
	cmd.Stdout = os.Stdout

	userOpts, userOptsSet := os.LookupEnv("_ZO_FZF_OPTS")
	if userOptsSet {
		env := removeEnv(os.Environ(), "FZF_DEFAULT_OPTS")
		env = append(env, "FZF_DEFAULT_OPTS="+userOpts)
		cmd.Env = env
	}

	if err := cmd.Run(); err != nil {
		if ee, ok := err.(*exec.ExitError); ok {
			return ee.ExitCode()
		}
		return 1
	}
	return 0
}
