package commands

import (
	"fmt"
	"os"
	"strings"

	"zoxide/internal/shell"
	"zoxide/internal/util"
)

func initHelp(progName string) string {
	return helpHeaderFor("init", "Generate shell configuration") + `

Usage:
  ` + progName + ` init [OPTIONS] <SHELL>

Arguments:
  <SHELL>  [possible values: bash, elvish, fish, nushell, posix, powershell, tcsh, xonsh, zsh]

Options:
      --no-cmd       Prevents zoxide from defining the ` + "`z`" + ` and ` + "`zi`" + ` commands
      --cmd <CMD>    Changes the prefix of the ` + "`z`" + ` and ` + "`zi`" + ` commands [default: z]
      --hook <HOOK>  Changes how often zoxide increments a directory's score [default: pwd] [possible values: none, prompt, pwd]
  -h, --help         Print help
  -V, --version      Print version

` + envVarsHelp
}

func RunInit(args []string, ctx Ctx) int {
	usageTail := "[OPTIONS] <SHELL>"
	var sh string
	shellSet := false
	cmd := "z"
	noCmd := false
	hook := "pwd"
	i := 0
	for i < len(args) {
		a := args[i]
		switch {
		case a == "-h" || a == "--help":
			fmt.Println(initHelp(ctx.ProgName))
			return 0
		case a == "-V" || a == "--version":
			fmt.Println("zoxide-init 0.9.9")
			return 0
		case a == "--":
			i++
			if i < len(args) {
				if shellSet {
					unexpectedArg(ctx, args[i], usageTail)
					return 2
				}
				sh = args[i]
				shellSet = true
				i++
			}
		case a == "--no-cmd":
			noCmd = true
			i++
		case a == "--cmd":
			i++
			if i >= len(args) {
				fmt.Fprintln(os.Stderr, "error: a value is required for '--cmd <CMD>' but none was supplied\n\nFor more information, try '--help'.")
				return 2
			}
			cmd = args[i]
			i++
		case strings.HasPrefix(a, "--cmd="):
			cmd = a[len("--cmd="):]
			i++
		case a == "--hook":
			i++
			if i >= len(args) {
				fmt.Fprintln(os.Stderr, "error: a value is required for '--hook <HOOK>' but none was supplied\n\nFor more information, try '--help'.")
				return 2
			}
			hook = args[i]
			i++
		case strings.HasPrefix(a, "--hook="):
			hook = a[len("--hook="):]
			i++
		case strings.HasPrefix(a, "-"):
			unexpectedArg(ctx, a, usageTail)
			return 2
		default:
			if shellSet {
				unexpectedArg(ctx, a, usageTail)
				return 2
			}
			sh = a
			shellSet = true
			i++
		}
	}
	if !shellSet {
		fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <SHELL>\n\nUsage: %s init <SHELL>\n\nFor more information, try '--help'.\n", ctx.ProgName)
		return 2
	}
	validShells := []string{"bash", "elvish", "fish", "nushell", "posix", "powershell", "tcsh", "xonsh", "zsh"}
	if !stringIn(sh, validShells) {
		fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '<SHELL>'\n  [possible values: bash, elvish, fish, nushell, posix, powershell, tcsh, xonsh, zsh]\n", sh)
		tip := util.SuggestFor(sh, validShells)
		if tip != "" {
			fmt.Fprintf(os.Stderr, "\n  tip: a similar value exists: '%s'\n", tip)
		}
		fmt.Fprintln(os.Stderr, "\nFor more information, try '--help'.")
		return 2
	}
	validHooks := []string{"none", "prompt", "pwd"}
	if !stringIn(hook, validHooks) {
		fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--hook <HOOK>'\n  [possible values: none, prompt, pwd]\n\nFor more information, try '--help'.\n", hook)
		return 2
	}

	out, err := shell.Render(sh, shell.Config{Cmd: cmd, Hook: hook, NoCmd: noCmd})
	if err != nil {
		fatalErr(err)
		return 1
	}
	fmt.Print(out)
	return 0
}

func stringIn(s string, list []string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}
GOEOF
