package shell

import (
	"embed"
	"fmt"
	"strings"
)

//go:embed templates/*.txt
var tmplFS embed.FS

type Config struct {
	Cmd   string
	Hook  string
	NoCmd bool
}

// Render returns the shell init script for the given shell with the given config.
func Render(sh string, c Config) (string, error) {
	if c.Hook == "" {
		c.Hook = "pwd"
	}
	if c.Cmd == "" && !c.NoCmd {
		c.Cmd = "z"
	}

	key := sh + "_" + c.Hook
	tmpl, err := tmplFS.ReadFile("templates/" + key + ".txt")
	if err != nil {
		return "", fmt.Errorf("unknown shell/hook: %s/%s", sh, c.Hook)
	}
	out := string(tmpl)

	if c.NoCmd {
		out = applyNoCmd(sh, out)
	} else {
		out = applyCmd(sh, out, c.Cmd)
	}

	return out, nil
}

// applyCmd substitutes the default 'z' and 'zi' with the user's cmd.
func applyCmd(sh, tmpl, cmd string) string {
	cmdI := cmd + "i"
	if cmd == "z" {
		return tmpl
	}
	switch sh {
	case "bash":
		tmpl = strings.Replace(tmpl, `\builtin unalias z &>/dev/null || \builtin true`+"\n"+`function z() {`, `\builtin unalias `+cmd+` &>/dev/null || \builtin true`+"\n"+`function `+cmd+`() {`, 1)
		tmpl = strings.Replace(tmpl, `\builtin unalias zi &>/dev/null || \builtin true`+"\n"+`function zi() {`, `\builtin unalias `+cmdI+` &>/dev/null || \builtin true`+"\n"+`function `+cmdI+`() {`, 1)
		tmpl = strings.Replace(tmpl, `READLINE_LINE="z ${__zoxide_result@Q}"`, `READLINE_LINE="`+cmd+` ${__zoxide_result@Q}"`, 1)
		tmpl = strings.Replace(tmpl, `\builtin complete -F __zoxide_z_complete -o filenames -- z`, `\builtin complete -F __zoxide_z_complete -o filenames -- `+cmd, 1)
		tmpl = strings.Replace(tmpl, `\builtin complete -r zi &>/dev/null || \builtin true`, `\builtin complete -r `+cmdI+` &>/dev/null || \builtin true`, 1)
	case "zsh":
		tmpl = strings.Replace(tmpl, "function z() {\n    __zoxide_z \"$@\"\n}", "function "+cmd+"() {\n    __zoxide_z \"$@\"\n}", 1)
		tmpl = strings.Replace(tmpl, "function zi() {\n    __zoxide_zi \"$@\"\n}", "function "+cmdI+"() {\n    __zoxide_zi \"$@\"\n}", 1)
		tmpl = strings.Replace(tmpl, `BUFFER="z ${(q-)__zoxide_result}"`, `BUFFER="`+cmd+` ${(q-)__zoxide_result}"`, 1)
		tmpl = strings.Replace(tmpl, `[[ "${+functions[compdef]}" -ne 0 ]] && \compdef __zoxide_z_complete z`, `[[ "${+functions[compdef]}" -ne 0 ]] && \compdef __zoxide_z_complete `+cmd, 1)
	case "posix":
		tmpl = strings.Replace(tmpl, `\command unalias z >/dev/null 2>&1 || \true`+"\n"+`z() {`, `\command unalias `+cmd+` >/dev/null 2>&1 || \true`+"\n"+cmd+`() {`, 1)
		tmpl = strings.Replace(tmpl, `\command unalias zi >/dev/null 2>&1 || \true`+"\n"+`zi() {`, `\command unalias `+cmdI+` >/dev/null 2>&1 || \true`+"\n"+cmdI+`() {`, 1)
	case "fish":
		tmpl = strings.Replace(tmpl, "abbr --erase z &>/dev/null\ncomplete --erase --command z\nalias z=__zoxide_z", "abbr --erase "+cmd+" &>/dev/null\ncomplete --erase --command "+cmd+"\nalias "+cmd+"=__zoxide_z", 1)
		tmpl = strings.Replace(tmpl, "abbr --erase zi &>/dev/null\ncomplete --erase --command zi\nalias zi=__zoxide_zi", "abbr --erase "+cmdI+" &>/dev/null\ncomplete --erase --command "+cmdI+"\nalias "+cmdI+"=__zoxide_zi", 1)
	case "tcsh":
		tmpl = strings.Replace(tmpl, "alias z __zoxide_z", "alias "+cmd+" __zoxide_z", 1)
		tmpl = strings.Replace(tmpl, "alias zi __zoxide_zi", "alias "+cmdI+" __zoxide_zi", 1)
	case "powershell":
		tmpl = strings.Replace(tmpl, "Set-Alias -Name z -Value __zoxide_z -Option AllScope -Scope Global -Force", "Set-Alias -Name "+cmd+" -Value __zoxide_z -Option AllScope -Scope Global -Force", 1)
		tmpl = strings.Replace(tmpl, "Set-Alias -Name zi -Value __zoxide_zi -Option AllScope -Scope Global -Force", "Set-Alias -Name "+cmdI+" -Value __zoxide_zi -Option AllScope -Scope Global -Force", 1)
	case "nushell":
		tmpl = strings.Replace(tmpl, "alias z = __zoxide_z", "alias "+cmd+" = __zoxide_z", 1)
		tmpl = strings.Replace(tmpl, "alias zi = __zoxide_zi", "alias "+cmdI+" = __zoxide_zi", 1)
	case "elvish":
		tmpl = strings.Replace(tmpl, "edit:add-var z~ $__zoxide_z~", "edit:add-var "+cmd+"~ $__zoxide_z~", 1)
		tmpl = strings.Replace(tmpl, "edit:add-var zi~ $__zoxide_zi~", "edit:add-var "+cmdI+"~ $__zoxide_zi~", 1)
		tmpl = strings.Replace(tmpl, "set edit:completion:arg-completer[z] = $__zoxide_z_complete~", "set edit:completion:arg-completer["+cmd+"] = $__zoxide_z_complete~", 1)
	case "xonsh":
		tmpl = strings.Replace(tmpl, `builtins.aliases["z"] = __zoxide_z`, `builtins.aliases["`+cmd+`"] = __zoxide_z`, 1)
		tmpl = strings.Replace(tmpl, `builtins.aliases["zi"] = __zoxide_zi`, `builtins.aliases["`+cmdI+`"] = __zoxide_zi`, 1)
	}
	return tmpl
}

// applyNoCmd replaces the commands block with "# -- not configured --".
func applyNoCmd(sh, tmpl string) string {
	switch sh {
	case "bash":
		return replaceBlock(tmpl, "\\builtin unalias z &>/dev/null", "fi\n", "# -- not configured --\n")
	case "zsh":
		// Remove z/zi function defs and compdef line; also change BUFFER to cd
		tmpl = replaceBlock(tmpl, "function z() {", "function zi() {\n    __zoxide_zi \"$@\"\n}\n", "# -- not configured --\n")
		tmpl = strings.Replace(tmpl, `BUFFER="z ${(q-)__zoxide_result}"`, `BUFFER="cd ${(q-)__zoxide_result}"`, 1)
		// Remove compdef line (and preceding empty line)
		tmpl = strings.Replace(tmpl, "\n\n    [[ \"${+functions[compdef]}\" -ne 0 ]] && \\compdef __zoxide_z_complete z", "", 1)
		return tmpl
	case "posix":
		return replaceBlock(tmpl, "\\command unalias z >/dev/null 2>&1", "zi() {\n    __zoxide_zi \"$@\"\n}\n", "# -- not configured --\n")
	case "fish":
		return replaceBlock(tmpl, "abbr --erase z ", "alias zi=__zoxide_zi\n", "# -- not configured --\n")
	case "tcsh":
		return replaceBlock(tmpl, "alias z __zoxide_z", "alias zi __zoxide_zi\n", "# -- not configured --\n")
	case "powershell":
		return replaceBlock(tmpl, "Set-Alias -Name z -Value __zoxide_z", "Set-Alias -Name zi -Value __zoxide_zi -Option AllScope -Scope Global -Force\n", "# -- not configured --\n")
	case "nushell":
		return replaceBlock(tmpl, "alias z = __zoxide_z", "alias zi = __zoxide_zi\n", "# -- not configured --\n")
	case "elvish":
		return replaceBlock(tmpl, "edit:add-var z~", "set edit:completion:arg-completer[z] = $__zoxide_z_complete~\n", "# -- not configured --\n")
	case "xonsh":
		return replaceBlock(tmpl, `builtins.aliases["z"]`, `builtins.aliases["zi"] = __zoxide_zi  # type: ignore  # pylint:disable=no-member`+"\n", "# -- not configured --\n")
	}
	return tmpl
}

// replaceBlock finds a block starting at startMarker and ending at (and including) endMarker,
// and replaces it with replacement.
func replaceBlock(s, startMarker, endMarker, replacement string) string {
	start := strings.Index(s, startMarker)
	if start < 0 {
		return s
	}
	end := strings.Index(s[start:], endMarker)
	if end < 0 {
		return s
	}
	end += start + len(endMarker)
	return s[:start] + replacement + s[end:]
}
