package main

import (
	"fmt"
	"strings"
)

func matchesKeywordsCore(path string, keywords []string) bool {
	if len(keywords) == 0 {
		return true
	}
	p := strings.ToLower(path)
	start := 0
	for _, kw := range keywords {
		kwl := strings.ToLower(kw)
		if kwl == "" {
			continue
		}
		idx := strings.Index(p[start:], kwl)
		if idx < 0 {
			fmt.Printf("kw %q not found in %q starting at %d\n", kwl, p, start)
			return false
		}
		start += idx + len(kwl)
	}
	lastKw := strings.ToLower(keywords[len(keywords)-1])
	if lastKw == "" {
		return true
	}
	lastSlash := strings.LastIndex(p, "/")
	lastSeg := p
	if lastSlash >= 0 {
		lastSeg = p[lastSlash+1:]
	}
	if !strings.Contains(lastSeg, lastKw) {
		fmt.Printf("lastKw %q not in lastSeg %q\n", lastKw, lastSeg)
		return false
	}
	return true
}

func main() {
	fmt.Println(matchesKeywordsCore("/tmp/日本語", []string{"日本"}))
	fmt.Println(matchesKeywordsCore("/tmp/日本語", []string{"日本語"}))
}
EOF
go run /tmp/test_match.go

